const body = msg.payload || {};

const actionMap = {
  temporary_isolate: "TEMPORARY_ISOLATE",
  quarantine: "PERMANENT_QUARANTINE",
  shutdown: "PERMANENT_QUARANTINE",
  rollback: "ROLLBACK",
  restore: "ALL_CLEAR",
  monitor: "MONITOR",
  log_and_monitor: "MONITOR"
};

const deviceMap = {
  "890cc34f": "PULSE_ESP32_001",
  "PULSE_ESP32_001": "PULSE_ESP32_001",
  "ECG_ESP32_001": "ECG_ESP32_001",
  "TEMP_ESP32_001": "TEMP_ESP32_003",
  "TEMP_ESP32_003": "TEMP_ESP32_003",
  "MOTION_ESP32_001": "FALL_ESP32_004",
  "FALL_ESP32_004": "FALL_ESP32_004"
};

if (!body.device_id) {
  const errorMsg = {
    payload: {
      ok: false,
      error: "Missing device_id"
    },
    statusCode: 400,
    headers: {
      "Content-Type": "application/json"
    }
  };
  return [null, errorMsg];
}

const sourceDeviceId = String(body.device_id);
const resolvedDeviceId = deviceMap[sourceDeviceId] || sourceDeviceId;
const requestedAction = String(body.action || body.requested_action || body.command || "monitor");
const normalizedCommand = actionMap[requestedAction.toLowerCase()] || String(body.command || requestedAction || "MONITOR").toUpperCase();
const topic = body.command_topic || `hospital/iomt/command/${resolvedDeviceId}`;

const commandPayload = {
  command: normalizedCommand,
  requested_action: requestedAction,
  command_id: body.command_id || `NR-${Date.now()}`,
  device_id: resolvedDeviceId,
  source_device_id: sourceDeviceId,
  command_topic: topic,
  telemetry_topic: body.telemetry_topic || null,
  metadata: body.metadata || {},
  issued_by: body.requested_by || "node-red",
  forwarded_at: new Date().toISOString()
};

msg.topic = topic;
msg.qos = 1;
msg.retain = false;
msg.payload = JSON.stringify(commandPayload);

const responseMsg = {
  payload: {
    ok: true,
    routed: true,
    forward_mode: "http-to-mqtt",
    device_id: resolvedDeviceId,
    source_device_id: sourceDeviceId,
    command_topic: topic,
    command: normalizedCommand,
    requested_action: requestedAction
  },
  statusCode: 200,
  headers: {
    "Content-Type": "application/json"
  }
};

return [msg, responseMsg];
